#!/usr/bin/env python3
# Copyright (c) 2026 Bernhard Haumacher
#
# Writes bulk.c: a block of about 20 KB of WebAssembly (issue #59, question 6: load and validation
# time of a module of the size a real block may reach). 80 functions of mixed integer and double
# arithmetic with branches, reached through one export, so nothing is dead code.
import sys

N = 80
out = open(sys.argv[1], "w")
out.write("""/*
 * Copyright (c) 2026 Bernhard Haumacher
 */

/* GENERATED by gen_bulk.py: a module of about 20 KB for the load measurements (issue #59). */

#include "../../abi/hc_block.h"

""")
for i in range(N):
	a, b, c = 3 + i % 7, 11 + i % 13, 1 + i % 5
	out.write(f"""__attribute__((noinline)) static double f{i}(double x, int32_t n)
{{
	double y = x * {a}.25 - {b}.5;
	int32_t k = n * {a} + {b};
	for (int32_t j = 0; j < {c}; j++) {{
		if (y > {b}.0)
			y = y / {c + 1}.5 + (double)(k % {c + 2});
		else
			y = y * 1.0{i % 9 + 1} + (double)(k ^ j);
		k = (k << 1) ^ (k >> 3) ^ {i * 2654435761 % 65536};
	}}
	return y + (double)(k & 1023) * 0.001;
}}

""")
out.write("HC_EXPORT(\"hc_abi\") int32_t abi(void)\n{\n\treturn HC_ABI_VERSION;\n}\n\n")
out.write("HC_EXPORT(\"bulk\") double bulk(int32_t i, double x)\n{\n\tswitch (i) {\n")
for i in range(N):
	out.write(f"\tcase {i}:\n\t\treturn f{i}(x, i);\n")
out.write("\tdefault:\n\t\treturn hc_read(0);\n\t}\n}\n")
